INSERT INTO projects (id, slug, draft_meta_json, draft_body_json, draft_version, created_at, updated_at) VALUES ('exhibition-booth-1', 'exhibition-booth-1', '{"categoryId":"blender","title":"Exhibition Booth 1 - THAIFEX 2025","shortTitle":"Exhibition Booth 1","subtitle":"A futuristic Nam Viet Group exhibition booth designed for THAIFEX 2025, combining kinetic product displays with a clear visitor experience.","thumbnailAssetId":"exhibition-thumbnail","coverAssetId":"exhibition-ex6","tags":["3d","blender","booth","exhibition","thaifex","nam viet","spatial design"],"tools":["Blender","3D visualization","Spatial design"],"role":"Exhibition environment & 3D visualization","year":"2025","isFeatured":false,"sortOrder":3}', '{"schemaVersion":1,"blocks":[{"id":"exhibition-hero","type":"image","assetId":"exhibition-ex6","alt":"Nam Viet Group exhibition booth perspective render","fit":"contain","style":{"width":"full"}},{"id":"exhibition-divider-1","type":"image","assetId":"exhibition-divider","alt":"Nam Viet Group green section divider","fit":"contain","style":{"width":"full"}},{"id":"exhibition-intro-title","type":"heading","level":2,"text":"THAIFEX 2025","style":{"width":"full"}},{"id":"exhibition-intro-copy","type":"text","style":{"width":"full"},"paragraphs":[{"spans":[{"text":"Nam Viet Group is a leading food and beverage exporter in Vietnam, offering a diverse product portfolio with fruit juices as its flagship line."}]},{"spans":[{"text":"Project: Nam Viet Group Exhibition Booth at THAIFEX 2025 (Thailand) — one of the year''s premier food and beverage trade fairs, bringing together distributors, importers, and industry partners nationwide."}]},{"spans":[{"text":"Booth Dimensions: 9m × 6m (54 m²)","bold":true}]}]},{"id":"exhibition-views","type":"image","assetId":"exhibition-artboard-3","alt":"Nam Viet Group exhibition booth front and angled views","fit":"contain","style":{"width":"full"}},{"id":"exhibition-divider-2","type":"image","assetId":"exhibition-divider","alt":"Nam Viet Group green section divider","fit":"contain","style":{"width":"full"}},{"id":"exhibition-key-title","type":"heading","level":2,"text":"KEY DIFFERENTIATOR","style":{"width":"full"}},{"id":"exhibition-key","type":"columns","columns":[[{"id":"exhibition-key-image","type":"image","assetId":"exhibition-ex5","alt":"Close-up of the Nam Viet Group booth centrepiece","fit":"contain","style":{"width":"full"}}],[{"id":"exhibition-key-copy","type":"text","style":{"width":"full"},"paragraphs":[{"spans":[{"text":"Key Visual & Brand Positioning:\nThe booth makes a striking impression with colossal beverage cans, instantly communicating the core business to international importers and making it seamless to attract and connect with target clients."}]},{"spans":[{"text":"Design Concept:\nBoasting a unique aesthetic inspired by a futuristic spaceship and an automated mega-factory, the architectural structure powerfully elevates brand presence, showcasing the scale and stature of one of Vietnam''s leading enterprises."}]},{"spans":[{"text":"Kinetic Highlights:\nTwo massive front pillars and the central giant can feature continuous rotation, creating a lively, captivating visual experience that outshines conventional static booths."}]}]}]],"style":{"width":"full"}},{"id":"exhibition-dimensions","type":"image","assetId":"exhibition-artboard-5","alt":"Detailed dimension drawings and overhead render of the booth","fit":"contain","style":{"width":"full"}},{"id":"exhibition-onsite","type":"image","assetId":"exhibition-artboard-6","alt":"On-site photos of Nam Viet Group at THAIFEX 2025","fit":"contain","style":{"width":"full"}},{"id":"exhibition-thanks-title","type":"heading","level":2,"text":"Thank you for watching","style":{"width":"full"}},{"id":"exhibition-thanks-copy","type":"text","style":{"width":"full"},"paragraphs":[{"spans":[{"text":"If you want to build your own brand, please click the Create button on the left side of the screen."}]},{"spans":[{"text":"Wishing you good health!"}]}]}]}', 1, '2026-10-14T00:00:00.000Z', '2026-10-14T00:00:00.000Z') ON CONFLICT(id) DO NOTHING;
